#!/usr/bin/env bash
# Workcenter — the local test certificate authority.
#
# Shared by `scripts/setup-testing.sh` and `scripts/e2e.sh`, and shared because a
# certificate generated by two different programs is two certificates: the browser
# trusts whichever one the trust store received, and the stack then serves the
# other. One implementation is what makes "the authority the setup script installed
# is the authority Traefik serves" true by construction rather than by discipline.
#
# The order of operations is the whole point of the split:
#
#   1. `scripts/setup-testing.sh` **creates** the authority if it is absent and
#      installs it in the trust stores. It runs before the stack exists.
#   2. `scripts/e2e.sh` **reuses** it. It only generates one when there is none,
#      which is the headless case where nobody ran the setup script and nobody is
#      going to open a browser.
#
# The caller must set `ROOT_DIR` and the seven hostname variables, and must define
# `ok`, `info`, `warn` and `fail`.
#
# It is a **CA plus a leaf**, not one self-signed certificate, and the difference is
# not cosmetic:
#
#   * `openssl req -x509` writes `Basic Constraints: critical CA:TRUE` into the
#     certificate it produces, and that certificate was then used as the *server*
#     certificate. OpenSSL, curl, Chrome and NSS's own `certutil -V` all accept
#     that. **Firefox does not**: it verifies with mozillapkix, which refuses a CA
#     certificate used as an end entity —
#     `MOZILLA_PKIX_ERROR_CA_CERT_USED_AS_END_ENTITY`. Firefox then refuses the
#     connection outright, so the shell shows its "untrusted certificate" page and
#     every pane is blank, no matter what is installed into any trust store: the
#     profile's `cert9.db` can hold the certificate with trust `C,,`, the system
#     store can hold it, and `curl` can verify every hostname, and Firefox still
#     refuses to load the page.
#   * A leaf with `CA:FALSE`, `keyUsage` and `extendedKeyUsage=serverAuth`, signed
#     by a long-lived local CA, is a shape every client accepts.
#
# The CA is the only thing a trust store ever receives, so re-signing a leaf does
# not invalidate a trust decision an operator already made — which is why the leaf
# is the short-lived half and the authority is not.

# The name a trust store knows this authority by.
readonly LOCALCA_STORE_NAME="workcenter-local-test"

# Every name the deployment serves, as an OpenSSL SAN list.
#
# Each one is here for a reason: the shell reaches the applications through Traefik
# by these names and verifies the certificate it is given (IN-1.5); `auth.` because
# every OIDC redirect crosses between the shell and the identity provider, and a
# browser that trusts one end must trust the other; `traefik.` because the dashboard
# is a surface the run proves access to. A certificate that omits one leaves the
# broker reporting that application unreachable, and gives a browser a hostname
# mismatch where the honest warning is only an untrusted issuer.
localca_san() {
  printf 'DNS:localhost,DNS:%s,DNS:%s,DNS:%s,DNS:%s,DNS:%s,DNS:%s,DNS:%s,IP:127.0.0.1' \
    "${WORKCENTER_HOST}" "${FILEBROWSER_HOST}" "${CHAT_HOST}" "${MAIL_HOST}" \
    "${OFFICE_HOST}" "${TRAEFIK_HOST}" "${AUTHENTIK_HOST}"
}

localca_ca_crt() { printf '%s/Traefik/certs/local-ca.crt' "${ROOT_DIR}"; }
localca_leaf_crt() { printf '%s/Traefik/certs/local.crt' "${ROOT_DIR}"; }

# Is the leaf a *leaf* — issued by something else — rather than the self-signed
# shape this project used to generate? A certificate that is its own issuer is the
# one Firefox refuses, so it is treated as absent.
localca_leaf_is_valid_shape() {
  local leaf; leaf="$(localca_leaf_crt)"
  [[ -f "${leaf}" ]] || return 1
  [[ "$(openssl x509 -in "${leaf}" -noout -issuer 2>/dev/null | sed 's/^issuer=//')" \
     != "$(openssl x509 -in "${leaf}" -noout -subject 2>/dev/null | sed 's/^subject=//')" ]]
}

# Generate the authority and a leaf it signs, unless both are already there.
#
# Sets `LOCALCA_CREATED=1` when it wrote files, so a caller that keeps a manifest
# can record them; `LOCALCA_REASON` says why it did nothing, for the caller's
# message. Always returns 0: a certificate that cannot be generated is reported and
# the caller decides whether that is fatal.
localca_ensure() {
  LOCALCA_CREATED=0
  local ca_crt ca_key leaf_crt leaf_key san
  ca_crt="$(localca_ca_crt)"
  ca_key="${ROOT_DIR}/Traefik/certs/local-ca.key"
  leaf_crt="$(localca_leaf_crt)"
  leaf_key="${ROOT_DIR}/Traefik/certs/local.key"
  san="$(localca_san)"

  if ! command -v openssl >/dev/null 2>&1; then
    warn 'openssl is not installed: cannot generate the local certificate'
    return 0
  fi

  if [[ -f "${leaf_crt}" && -f "${ca_crt}" ]] && localca_leaf_is_valid_shape; then
    # An operator may have put a certificate they trust here on purpose, so a leaf
    # that does not name the application host is a warning with the remedy rather
    # than a regeneration.
    if ! openssl x509 -in "${leaf_crt}" -noout -ext subjectAltName 2>/dev/null \
        | grep -qiF "DNS:${FILEBROWSER_HOST}"; then
      warn "Traefik/certs/local.crt does not name ${FILEBROWSER_HOST}"
      warn 'the shell will report the applications unreachable: remove Traefik/certs/local.crt and'
      warn 'Traefik/certs/local.key, then re-run, to generate one covering every test hostname'
    else
      info 'local certificate already present'
    fi
    return 0
  fi

  mkdir -p "${ROOT_DIR}/Traefik/certs" 2>/dev/null || true
  local csr="${ROOT_DIR}/Traefik/certs/local.csr"
  local log="${LOCALCA_LOG:-/dev/null}"
  if ! {
    openssl req -x509 -newkey rsa:2048 -nodes -days 3650 \
      -keyout "${ca_key}" -out "${ca_crt}" \
      -subj '/CN=Workcenter local test CA' \
      -addext 'basicConstraints=critical,CA:TRUE' \
      -addext 'keyUsage=critical,keyCertSign,cRLSign'
    openssl req -newkey rsa:2048 -nodes -keyout "${leaf_key}" -out "${csr}" \
      -subj '/CN=Workcenter local test' \
      -addext "subjectAltName=${san}"
    openssl x509 -req -in "${csr}" -CA "${ca_crt}" -CAkey "${ca_key}" -CAcreateserial \
      -days 30 -out "${leaf_crt}" \
      -extfile <(printf 'basicConstraints=critical,CA:FALSE\nkeyUsage=critical,digitalSignature,keyEncipherment\nextendedKeyUsage=serverAuth\nsubjectAltName=%s\n' "${san}")
  } >"${log}" 2>&1; then
    fail 'could not generate the local certificate'
    return 0
  fi
  rm -f "${csr}" "${ROOT_DIR}/Traefik/certs/local-ca.srl"
  LOCALCA_CREATED=1
  ok 'generated the local certificate authority and a leaf certificate it signs'
  info "the authority is what a trust store receives: ${ca_crt#"${ROOT_DIR}/"}"
}

# Where this distribution keeps a locally-trusted certificate, and the command that
# refreshes its bundle. Echoes "<directory>|<refresh command>", "p11-kit|trust
# anchor", or nothing when the layout is not recognised.
#
# The refresh tool has to exist, not merely the directory: writing an anchor into a
# directory whose bundle is never rebuilt looks like success and changes nothing —
# which is exactly what happened when this assumed Debian's path on Arch.
localca_anchor_dir() {
  local dir refresh
  while IFS='|' read -r dir refresh; do
    [[ -n "${dir}" ]] || continue
    if [[ -d "${dir}" ]] && command -v "${refresh}" >/dev/null 2>&1; then
      printf '%s|%s' "${dir}" "${refresh}"
      return 0
    fi
  done <<'STORES'
/usr/local/share/ca-certificates|update-ca-certificates
/etc/ca-certificates/trust-source/anchors|update-ca-trust
/etc/pki/ca-trust/source/anchors|update-ca-trust
/etc/pki/trust/anchors|update-ca-certificates
STORES
  if command -v trust >/dev/null 2>&1; then
    printf 'p11-kit|trust anchor'
  fi
  return 0
}

# Is the authority installed in a system trust store?
#
# Every known directory is checked, and the refresh tool is *not* required: a trust
# store can hold the anchor with its bundle already rebuilt, and this predicate is
# read by `scripts/e2e.sh` as its preflight — a false negative there tells a person
# to re-run a command they have already run. Readable by anyone, so the harness can
# ask without privilege.
localca_installed() {
  local dir
  for dir in \
    /usr/local/share/ca-certificates \
    /etc/ca-certificates/trust-source/anchors \
    /etc/pki/ca-trust/source/anchors \
    /etc/pki/trust/anchors; do
    [[ -f "${dir}/${LOCALCA_STORE_NAME}.crt" ]] && return 0
  done
  # A p11-kit store has no inspectable layout without root, so it cannot be
  # confirmed from here; the harness reports that as "cannot tell" rather than
  # "missing".
  return 1
}
